
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_gds08_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_gds08", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.641625405250069e+01, 2.635486634755940e+01, 2.626498338831006e+01, 2.613327277016121e+01, 2.594080685837226e+01, 2.566168230395893e+01, 2.526004132125845e+01, 2.467011959822665e+01, 2.366467039159678e+01, 2.109786895654854e+01, 1.252242876165156e+01, 1.872661214731506e+00, 1.008010038965439e+00, 1.140505959484486e+00, 1.038804355638617e+00, 6.696263432521377e-01, 8.974927790305383e-02, -7.043044734588124e-01, -1.778547244969180e+00, -3.271765049376515e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


